mapper.select:
SELECT a.board_id, b.category_name, b.category_name_kh, b.category_code, a.board_title_en, a.board_html_en, a.board_title_kh, a.board_html_kh, a.created_date FROM bbs_board a INNER JOIN bbs_category b ON b.category_code = a.category_code WHERE b.parent_category_code = '015' AND a.is_deleted = 0
AND ( a.board_title_en LIKE CONCAT('%', #{dataGridDTO.searchKeyword}, '%') OR a.board_html_en ILIKE CONCAT('%', #{dataGridDTO.searchKeyword}, '%') OR b.category_name ILIKE CONCAT('%', #{dataGridDTO.searchKeyword}, '%') OR b.category_name_kh ILIKE CONCAT('%', #{dataGridDTO.searchKeyword}, '%') OR a.board_title_kh LIKE CONCAT('%', #{dataGridDTO.searchKeyword}, '%') OR a.board_html_kh ILIKE CONCAT('%', #{dataGridDTO.searchKeyword}, '%') )
LIMIT #{dataGridDTO.pageSize} OFFSET #{dataGridDTO.start}
